def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    ones = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    # Fill diagonal intervals between aligned 1 markers, keeping 6s visible.
    orientations = []
    for i,(r,c) in enumerate(ones):
        for rr,cc in ones[i+1:]:
            if abs(rr-r) == abs(cc-c) and rr != r:
                dr = 1 if rr > r else -1
                dc = 1 if cc > c else -1
                orientations.append(dr*dc)
                for k in range(1, abs(rr-r)):
                    y,x = r+dr*k,c+dc*k
                    if out[y][x] != 6:
                        out[y][x] = 1
    # A 6 runs along the diagonal orientation perpendicular to the 1-connector.
    if sixes and orientations:
        sign = -orientations[0]
        for r,c in sixes:
            for dr in (-1,1):
                dc = sign*dr
                y,x=r,c
                while 0 <= y-dr < h and 0 <= x-dc < w:
                    y-=dr; x-=dc
                while 0 <= y < h and 0 <= x < w:
                    if out[y][x] != 1:
                        out[y][x]=6
                    y+=dr; x+=dc
